"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["88196"],{86113(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.item_formulario.fato_codigo_tamanho","status":422,"titulo":"O c\xf3digo do fato do item excede o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.item_formulario.fato_codigo_tamanho","requisitos":[],"oQueAconteceu":["O `fatoCodigo` de um item do formul\xe1rio, ou de um campo de grupo, tem mais de 50 caracteres. A mensagem \xe9 \\"O c\xf3digo do fato do item deve ter no m\xe1ximo 50 caracteres.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `itens[i].fatoCodigo` ou, no campo de um grupo, `grupos[g].subitens[j].fatoCodigo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Cada item recusado tem a pr\xf3pria entrada, junto das demais recusas da forma do item. O item de forma recusada n\xe3o segue para a confer\xeancia contra o cat\xe1logo de fatos. Nada \xe9 gravado. Nos modelos, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["Informe em `fatoCodigo` o c\xf3digo de um fato do cat\xe1logo de fatos do candidato, que tem at\xe9 50 caracteres."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o dos itens do formul\xe1rio"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Item formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);